// ── Node.js full instrumentation with prom-client ─────────────────
import express from 'express';
import client from 'prom-client';

const app = express();

// 1. Collect built-in Node.js metrics (event loop lag, GC duration,
//    heap used/total, active handles, active requests, etc.)
client.collectDefaultMetrics({ prefix: 'api_' });

// 2. Counter — label by method, route, and HTTP status code
//    This single metric powers all three RED signals:
//    Rate   = rate(http_requests_total[5m])
//    Errors = rate(http_requests_total{status_code=~"5.."}[5m])
//               / rate(http_requests_total[5m])
const httpRequestsTotal = new client.Counter({
  name: 'http_requests_total',
  help: 'Total HTTP requests received',
  labelNames: ['method', 'route', 'status_code'],
});

// 3. Histogram — buckets tuned for a typical web API
//    Duration = histogram_quantile(0.99,
//                 rate(http_request_duration_seconds_bucket[5m]))
const httpRequestDurationSeconds = new client.Histogram({
  name: 'http_request_duration_seconds',
  help: 'HTTP request latency in seconds',
  labelNames: ['method', 'route', 'status_code'],
  buckets: [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5],
});

// 4. Gauge — in-flight requests (USE: saturation proxy)
const httpActiveRequests = new client.Gauge({
  name: 'http_active_requests',
  help: 'Number of in-flight HTTP requests currently being processed',
});

// 5. Gauge — queue depth (USE: saturation for a background worker)
const jobQueueDepth = new client.Gauge({
  name: 'job_queue_depth',
  help: 'Number of jobs waiting in the processing queue',
});

// 6. Middleware: instrument every request transparently
app.use((req, res, next) => {
  const timer = httpRequestDurationSeconds.startTimer();
  httpActiveRequests.inc();

  res.on('finish', () => {
    const labels = {
      method: req.method,
      route: req.route?.path ?? 'unknown',
      status_code: String(res.statusCode),
    };
    httpRequestsTotal.inc(labels);
    timer(labels);           // records elapsed seconds into histogram
    httpActiveRequests.dec();
  });

  next();
});

// 7. /metrics endpoint — Prometheus scrapes this every 15 seconds
app.get('/metrics', async (_req, res) => {
  res.set('Content-Type', client.register.contentType);
  res.send(await client.register.metrics());
});

// 8. Business endpoint — all instrumentation is in the middleware
app.get('/orders/:id', async (req, res) => {
  const order = await db.findOrder(req.params.id);
  if (!order) return res.status(404).json({ error: 'not found' });
  res.json(order);
});

app.listen(3000, () =>
  console.log('Server :3000 | metrics :3000/metrics')
);
